WITH filtered AS (SELECT id, name, email, country, segment, signup_date, is_active, credit_limit, CAST(is_active AS INT) is_active_flag FROM customers WHERE signup_date > DATE '2023-04-23' AND segment IS NOT NULL) SELECT CASE WHEN is_active_flag >= 70 THEN 'HIGH' ELSE 'LOW' END AS is_active_flag_tier, SORT_ARRAY(COLLECT_SET(country)) AS country_list, ROUND(AVG(credit_limit), 2) AS avg_credit_limit, ROUND(AVG(is_active_flag), 2) AS avg_is_active_flag, SIZE(COLLECT_SET(segment)) AS num_segments, SUM(CASE WHEN country = 'DE' THEN is_active_flag ELSE 0 END) AS de_is_active_flag, PERCENTILE_APPROX(credit_limit, 0.9) AS credit_limit_p90 FROM filtered GROUP BY CASE WHEN is_active_flag >= 70 THEN 'HIGH' ELSE 'LOW' END ORDER BY credit_limit_p90 DESC
